fn x_ssq(dst: mem1d_dsd) void {
  // (trm 2) B 1: the squares summed into dst by one stride-0 accumulate
  @fmuls(sqx_t(), x_all, x_all);
  @fmovs(dst, 0.0);
  const acc = @set_dsd_length(@set_dsd_stride(dst, 0), Hc);
  @fadds(acc, acc, @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{Hc} -> s[i] }));
}
